Carpooling.Move.Expanding.source:
def Move.Expanding {x y : V → ℝ} (e : Move x y) : Prop :=
  x e.v < x e.u + e.weight

omit [Fintype V] in

Carpooling.Run.Closed.source:
def Run.Closed {T : ℕ} (R : Run V T) (C : Finset V) : Prop :=
  ∀ t (ht : t < T), (R.step t ht).u ∈ C ↔ (R.step t ht).v ∈ C

/-- Ignore moves outside C by replacing their weight by zero. -/

Carpooling.Run.LocalInternal.source:
def Run.LocalInternal {T : ℕ} (R : Run V T) (C : Finset V) (t : ℕ) : Prop :=
  ∃ h : t < T, (R.clusters t).block (R.step t h).u = (R.clusters t).block (R.step t h).v ∧
    (R.step t h).u ∈ C

Carpooling.lowerPair.source:
noncomputable def lowerPair (h : ℕ) (x : Fin (2*h+2) → ℤ) :
    Fin (2*h+2) × Fin (2*h+2) :=
  if he : ∃ u v, u ≠ v ∧ x u = x v then (he.choose,he.choose_spec.choose)
  else (⟨0,by omega⟩,⟨1,by omega⟩)

Carpooling.threshold.source:
def threshold (D : ℝ) (r : ℕ) : ℝ := (r : ℝ) * (D - r + 1)

/-- The first-crossing argument, separated from the finite-set bookkeeping.
All hypotheses are established for actual top sums below. -/

Carpooling.Witness.edges.source:
def edges (root : V) : Tree V → Multiset (Sym2 V)
  | .nil => 0
  | .node v L R => {s(root,v)} + edges v L + edges root R

Carpooling.Witness.vertices.source:
def vertices (root : V) : Tree V → Finset V
  | .nil => {root}
  | .node v L R => vertices v L ∪ vertices root R
